package com.example.library;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import org.springframework.security.test.context.support.WithMockUser;import org.springframework.mock.web.MockMultipartFile;import org.springframework.test.context.DynamicPropertySource;import org.springframework.test.context.DynamicPropertyRegistry;import java.nio.file.*;import javax.imageio.ImageIO;import java.awt.image.BufferedImage;import java.io.*;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:covers_test;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.database-platform=org.hibernate.dialect.H2Dialect","spring.jpa.hibernate.ddl-auto=create-drop","app.seed.enabled=false"}) @AutoConfigureMockMvc
class BookCoverIntegrationTest {
 @Autowired MockMvc mvc;@Autowired com.fasterxml.jackson.databind.ObjectMapper json;
 static Path folder;static{try{folder=Files.createTempDirectory("moc-covers-test-");}catch(IOException e){throw new ExceptionInInitializerError(e);}}
 @DynamicPropertySource static void properties(DynamicPropertyRegistry registry){registry.add("app.upload.book-covers",()->folder.toString());}
 @AfterAll static void clean()throws IOException{try(var files=Files.list(folder)){for(Path p:files.toList())Files.deleteIfExists(p);}Files.deleteIfExists(folder);}
 MockMultipartFile valid()throws IOException{var out=new ByteArrayOutputStream();ImageIO.write(new BufferedImage(16,24,BufferedImage.TYPE_INT_RGB),"png",out);return new MockMultipartFile("file","../../cover.png","image/png",out.toByteArray());}
 @Test @WithMockUser(roles="ADMIN") void adminUploadIsReencodedAndPublicImageCanBeRead()throws Exception{var response=mvc.perform(multipart("/api/v1/books/cover-upload").file(valid())).andExpect(status().isOk()).andReturn();String url=json.readTree(response.getResponse().getContentAsString()).path("url").asText();assertTrue(url.matches("/images/book-covers/[a-f0-9]{32}\\.png"));var saved=mvc.perform(get(url)).andExpect(status().isOk()).andExpect(content().contentType("image/png")).andExpect(header().string("X-Content-Type-Options","nosniff")).andReturn();assertNotNull(ImageIO.read(new ByteArrayInputStream(saved.getResponse().getContentAsByteArray())));try(var files=Files.list(folder)){assertTrue(files.count()>=1);}}
 @Test @WithMockUser(roles="LIBRARIAN") void librarianCanUpload()throws Exception{mvc.perform(multipart("/api/v1/books/cover-upload").file(valid())).andExpect(status().isOk());}
 @Test @WithMockUser(roles="USER") void readerCannotUpload()throws Exception{mvc.perform(multipart("/api/v1/books/cover-upload").file(valid())).andExpect(status().isForbidden());}
 @Test void anonymousCannotUpload()throws Exception{mvc.perform(multipart("/api/v1/books/cover-upload").file(valid())).andExpect(status().isUnauthorized());}
 @Test @WithMockUser(roles="ADMIN") void svgOrFakeImageCannotUpload()throws Exception{mvc.perform(multipart("/api/v1/books/cover-upload").file(new MockMultipartFile("file","cover.svg","image/svg+xml","<svg onload=alert(1)></svg>".getBytes()))).andExpect(status().isBadRequest());mvc.perform(multipart("/api/v1/books/cover-upload").file(new MockMultipartFile("file","cover.png","image/png","not an image".getBytes()))).andExpect(status().isBadRequest());}
 @Test @WithMockUser(roles="ADMIN") void oversizedAndEmptyImagesAreRejected()throws Exception{mvc.perform(multipart("/api/v1/books/cover-upload").file(new MockMultipartFile("file","x.png","image/png",new byte[2*1024*1024+1]))).andExpect(status().isBadRequest());mvc.perform(multipart("/api/v1/books/cover-upload").file(new MockMultipartFile("file","x.png","image/png",new byte[0]))).andExpect(status().isBadRequest());}
 @Test void unknownImageIs404AndDoesNotExposeDiskPaths()throws Exception{mvc.perform(get("/images/book-covers/"+"a".repeat(32)+".png")).andExpect(status().isNotFound());mvc.perform(get("/images/book-covers/application.properties")).andExpect(status().isNotFound());}
}
